	final boolean isDebug = false;
	String fileName = "input.txt";
	FastScanner sc;
	//PrintWriter out;
	final int MOD = 1000000007;

	int N, A, B;
	int[] h;
	long max;

	/* solve */
	void solve(){
		N = sc.nextInt();
		A = sc.nextInt();
		B = sc.nextInt();
		h = new int[N];
		max = 1;
		for(int i = 0; i < N; i++){
			h[i] = sc.nextInt();
			max += (long)Math.ceil((double)h[i]/A);
		}
		Arrays.sort(h);
		System.out.println(binarySearch());
