	boolean isOk(long k){
		long damageAll = (long)B * k;
		long damageAdd = A - B;

		long count = 0;
		for(int i = 0; i < N; i++){
			if(h[i] <= damageAll) continue;
			count += (long)Math.ceil((double)(h[i]-damageAll) / damageAdd);			
		}

		return (count <= k) ? true : false;
	}

	long binarySearch(){
		/*
		 * 上界の探索
		 * 下界の場合は ok = a.length, ng = -1;
		 */
		long ok = max;
		long ng = -1;

		while(Math.abs(ok - ng) > 1){
			long mid = (ok + ng) / 2;
			if(isOk(mid)) ok = mid;
			else ng = mid;
		}

		return ok;
	}
