public class Main {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        ABC066b problem = new ABC066b(sc);
        out.println(problem.solve());

        out.flush();
    }

