class ABC066b {

    private final String S;

    ABC066b(FastScanner sc) {
        S = sc.next();
    }

    int solve() {
        final int N = S.length();
        for (int i = 1; i < N; i++) {
            String ss = S.substring(0,N-i);
            if (ss.length() % 2 != 0) continue;
            String s = ss.substring(0,ss.length()/2);
            if (ss.equals(s+s)) return ss.length();
        }
        return 0;
    }

}

