        PriorityQueue<Long> diff = new PriorityQueue<>(Collections.reverseOrder());
        for (int i = 1; i < m; ++i) {
            long currentDiff = x[i] - x[i - 1];
            diff.add(currentDiff);
        }
        for (int i = 0; i < n - 1; ++i) {
            long currentDiff = diff.poll();
            sum -= currentDiff;
        }
        System.out.println(sum);


