    public static boolean isPrime(int X) {
        if(X == 2) return true;
        if(X % 2 == 0) return false;

        double sqrtNum = Math.sqrt(X);

        for(int i=3; i<= sqrtNum; i += 2) {
            if(X % i == 0) return false;
        }
        return true;
    }
}
