        int count = 0;

        for(int i=0; i<num; i++){

            int min = i;
            for(int j=i; j<num; j++){

                if(arr[min] > arr[j]){
                    min = j;
                }
            }
            int tmp = arr[min];
            arr[min] = arr[i];
            arr[i] = tmp;
            if (min != i) {
                count++;
            }
        }
        return new Sort(count, arr);
    }
}

