a = list(map(int, input().split()))

def selectionSort(a:list, n:int):
    count = 0
    for i in range(n):
        flag = 0
        minj = i
        for j in range(i, n):
            if a[j] < a[minj]:
                minj = j
                flag = 1
        if flag:
            a[i], a[minj] = a[minj], a[i]
