                if (array[j] < array[minv]) {
                    minv = j;
                }
            }
            if (minv != i) {
                int tmp = array[i];
                array[i] = array[minv];
                array[minv] = tmp;
                cnt++;
            }
        }
        return cnt;
    }

}

