	 */
	private static int selectionSort(int n, int[] targetArray) {

		int exchangingCount = 0; // 入れ替え回数
		for (int i = 0; i < n; i++) {
			int minIndex = i; // 最小値の要素番号
			for (int j = i; j < n; j++) {
				// 最小値より低い値があったら
